def dehydrate_point(value):
    """
    Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: A tuple containing the point coordinates or None if the input is None.
    """
    try:
        # Handle None explicitly
        if value is None:
            return None

        # If it's a mapping with coordinate keys
        if isinstance(value, dict):
            if 'x' in value and 'y' in value:
                return (value['x'], value['y'])
            if 'lat' in value and 'lng' in value:
                return (value['lat'], value['lng'])
            if 'latitude' in value and 'longitude' in value:
                return (value['latitude'], value['longitude'])

        # If it's an iterable with two elements (e.g., list, tuple)
        if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
            try:
                it = iter(value)
                x = next(it)
                y = next(it)
                # Ensure there are no extra items
                try:
                    next(it)
                    raise ValueError("Iterable provided more than two elements")
                except StopIteration:
                    pass
                return (x, y)
            except Exception:
                pass

        # If it has x and y attributes
        if hasattr(value, "x") and hasattr(value, "y"):
            return (value.x, value.y)

        # If it has lat/lng attributes
        if hasattr(value, "lat") and hasattr(value, "lng"):
            return (value.lat, value.lng)

        # If it has latitude/longitude attributes
        if hasattr(value, "latitude") and hasattr(value, "longitude"):
            return (value.latitude, value.longitude)

        # If we reach here, the structure is not recognized
        raise TypeError(f"Unrecognized Point type: {type(value)!r}")

    except Exception as exc:
        # Convert any exception to a ValueError for consistency
        raise ValueError(f"Error dehydrating point: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Attempt to fetch the underlying dictionary that stores the record's data
    mapping = None
    try:
        mapping = getattr(self, "data")
    except AttributeError:
        pass
    if mapping is None:
        try:
            mapping = getattr(self, "_data")
        except AttributeError:
            pass
    if mapping is None:
        raise AttributeError(
            "The record instance does not contain a 'data' or '_data' attribute."
        )
    if not isinstance(mapping, dict):
        raise TypeError(
            f"The record's underlying data should be a dict, got {type(mapping).__name__}."
        )
    try:
        return list(mapping.keys())
    except Exception as e:
        raise ValueError(f"Failed to retrieve keys from the record: {e}") from e

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Validate input
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError(
                "protocol_version must be a tuple of integers, got %r"
                % (protocol_version,)
            )

        handlers = {}
        # Iterate over the class hierarchy, including base classes,
        # to find subclasses that expose a PROTOCOL_VERSION attribute.
        for base in cls.__mro__:
            for attr in base.__dict__.values():
                try:
                    if isinstance(attr, type) and isinstance(
                        getattr(attr, "PROTOCOL_VERSION", None), tuple
                    ):
                        # Use the version tuple as dictionary key.
                        handlers[attr.PROTOCOL_VERSION] = attr
                except Exception:
                    # Skip any attribute that raises an exception on access.
                    continue

        # If a specific version was requested, filter the result.
        if protocol_version is not None:
            if protocol_version in handlers:
                return {protocol_version: handlers[protocol_version]}
            else:
                return {}

        return handlers

def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out."""
    # Validate parameters
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict or None")
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a float, int or None")
        if timeout < 0:
            raise ValueError("timeout must not be negative")

    def decorator(func):
        def wrapper(*args, **kwargs):
            # The neo4j driver object must be supplied via a keyword argument
            driver = kwargs.pop('driver', None)
            if driver is None:
                raise RuntimeError("A Neo4j driver object must be supplied via the 'driver' keyword argument")
            # Import the driver inside the wrapper to avoid top-level imports
            try:
                from neo4j import GraphDatabase
            except Exception as exc:
                raise RuntimeError("Failed to import neo4j driver") from exc

            session = driver.session()
            tx = None
            try:
                # Begin a transaction, applying the optional timeout
                if timeout is not None:
                    # In the official neo4j driver, timeout is specified in milliseconds
                    # but the parameter name is 'timeout' in begin_transaction.
                    tx = session.begin_transaction(timeout=timeout)
                else:
                    tx = session.begin_transaction()

                # Attach metadata if provided
                if metadata:
                    try:
                        tx.run("CALL dbms.setTXMetaData($meta)", {'meta': metadata})
                    except Exception:
                        # If the metadata setting fails, still proceed with the transaction
                        pass

                # Execute the user-provided transaction function
                result = func(tx, *args, **kwargs)

                # Commit the transaction
                tx.commit()
                return result
            except Exception as exc:
                # Roll back on any exception and re-raise
                if tx is not None:
                    try:
                        tx.rollback()
                    except Exception:
                        pass
                raise exc
            finally:
                session.close()
        # Preserve the original function's metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__annotations__ = getattr(func, '__annotations__', {})
        return wrapper

    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    container = getattr(self, 'items', None)
    if container is None:
        container = self
    try:
        return list(container).index(key)
    except AttributeError:
        raise TypeError("Container does not support index operation.")
    except ValueError:
        raise ValueError(f"Key {key!r} not found.")
    except Exception as e:
        raise RuntimeError(f"Unexpected error during index lookup: {e}") from e

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine underlying data container
    data = None
    ordered_values = []

    # Try common container attributes
    if hasattr(self, "_data"):
        data = self._data
    elif hasattr(self, "data"):
        data = self.data
    elif hasattr(self, "__dict__"):
        data = getattr(self, "__dict__")

    # If we have explicit value list, use it; otherwise infer from data
    if hasattr(self, "_values"):
        ordered_values = list(self._values)
    elif isinstance(data, dict):
        # Preserve insertion order (Python 3.7+ guarantees)
        ordered_values = list(data.values())
    elif isinstance(data, (list, tuple)):
        ordered_values = list(data)
    else:
        # Fallback: iterate over attributes if any
        ordered_values = [getattr(self, k) for k in dir(self)
                          if not k.startswith("_") and not callable(getattr(self, k))]

    # If no keys specified, return all values
    if not keys:
        return ordered_values

    result = []
    for k in keys:
        # Handle index-based access
        if isinstance(k, int):
            try:
                result.append(ordered_values[k])
            except (IndexError, TypeError):
                # ignore invalid index
                continue
        # Handle key-based access
        else:
            if isinstance(data, dict):
                try:
                    result.append(data[k])
                except KeyError:
                    continue
            else:
                # Attempt to access attribute
                try:
                    result.append(getattr(self, k))
                except AttributeError:
                    continue
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Attempt to locate the internal storage of field names and values.
    # Common patterns are "fields" / "values" or "_keys" / "_values".
    field_names = None
    field_values = None

    if hasattr(self, "fields") and hasattr(self, "values"):
        field_names = self.fields
        field_values = self.values
    elif hasattr(self, "_keys") and hasattr(self, "_values"):
        field_names = self._keys
        field_values = self._values

    # Fallback: use the attributes present in the instance's __dict__.
    # This may not preserve order or index semantics, but provides a sane default.
    if field_names is None or field_values is None:
        try:
            field_names = list(vars(self).keys())
            field_values = [getattr(self, name) for name in field_names]
        except Exception as exc:
            raise AttributeError("Unable to introspect record fields") from exc

    # Ensure we are working with a list or tuple for indexing.
    if not isinstance(field_names, (list, tuple)):
        try:
            field_names = list(field_names)
        except Exception as exc:
            raise TypeError("Field names must be list or tuple") from exc
    if not isinstance(field_values, (list, tuple)):
        try:
            field_values = list(field_values)
        except Exception as exc:
            raise TypeError("Field values must be list or tuple") from exc

    total_items = len(field_names)
    if total_items != len(field_values):
        raise ValueError("Number of field names and values must match")

    # If no keys are supplied, return all fields.
    if not keys:
        return dict(zip(field_names, field_values))

    result = {}
    for key in keys:
        # Handle integer indexes (including negative indexes).
        if isinstance(key, int):
            idx = key
            if idx < 0:
                idx += total_items
            if idx < 0 or idx >= total_items:
                raise IndexError(f"Index {key} out of bounds for record of length {total_items}")
            result[field_names[idx]] = field_values[idx]
        else:
            # Treat as a field name (hashable). If not present, insert None.
            if key in field_names:
                idx = field_names.index(key)
                result[key] = field_values[idx]
            else:
                result[key] = None
    return result

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Usage:
        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    Each call to the decorated function will emit a DeprecationWarning
    with the supplied message.

    Raises:
        TypeError: If the supplied message is not a string or the
        target of the decorator is not callable.
    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError(f"Cannot decorate non-callable object: {func!r}")
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle a sequence of strings."""
    # Validate input
    if seq is None:
        raise TypeError("Input sequence cannot be None")
    # Accept list, tuple, or string; other sequences are allowed but must be iterable
    if not isinstance(seq, (list, tuple, str)):
        # Ensure it is iterable
        try:
            iter(seq)
        except TypeError:
            raise TypeError("Input must be a sequence of strings")
    # Check that every element is a string
    for item in seq:
        if not isinstance(item, str):
            raise TypeError("All elements of the sequence must be strings")
    # Perform deterministic Fisher-Yates shuffle
    result = list(seq)
    n = len(result)
    for i in range(n - 1, 0, -1):
        v = result[i]
        # Deterministic pseudo-random seed derived from element value and index
        seed = sum(ord(c) for c in v) + i * 7681
        j = seed % (i + 1)
        result[i], result[j] = result[j], result[i]
    return result

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    import re
    # Extract all contiguous digit sequences
    numbers = re.findall(r'\d+', s)
    if not numbers:
        return ()
    try:
        return tuple(int(n) for n in numbers)
    except Exception as exc:  # pragma: no cover
        raise ValueError(f"Could not parse version string '{s}'") from exc

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache."""
    if cache is None:
        # If no cache provided, return the original function unchanged
        def decorator(func):
            return func
        return decorator

    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute cache key
            try:
                cache_key = key(*args, **kwargs)
            except Exception:
                # If key function fails, just call the original function
                return func(*args, **kwargs)

            # Attempt to retrieve the cached value
            try:
                if lock is not None:
                    with lock:
                        cached_value = cache[cache_key]
                else:
                    cached_value = cache[cache_key]
                return cached_value
            except Exception:
                # Key not found or cache lookup failed; proceed to compute
                pass

            # Compute the result since it's not cached or cache lookup failed
            result = func(*args, **kwargs)

            # Store the result in the cache
            try:
                cache[cache_key] = result
            except Exception:
                # Ignore any failure to update the cache
                pass

            return result

        return wrapper

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        lru = []

        def wrapper(*args, **kwargs):
            # Build key
            key = args
            if kwargs:
                # To ensure order-insensitivity, sort kwargs items
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types in the key if typed=True
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))

            now = timer()
            try:
                result, stamp = cache[key]
            except KeyError:
                pass
            else:
                if now - stamp <= ttl:
                    # Cache hit and not expired: update LRU order
                    if key in lru:
                        lru.remove(key)
                    lru.append(key)
                    return result
                else:
                    # Expired entry: remove from cache and lru
                    try:
                        del cache[key]
                    except KeyError:
                        pass
                    try:
                        lru.remove(key)
                    except ValueError:
                        pass

            # Cache miss or expired: compute new result
            result = func(*args, **kwargs)
            cache[key] = (result, now)
            lru.append(key)

            # Enforce maxsize by evicting least recently used item
            if len(cache) > maxsize:
                oldest_key = lru.pop(0)
                cache.pop(oldest_key, None)

            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty") from None
    if hasattr(self, "pop"):
        value = self.pop(first_key)
    else:
        value = self[first_key]
        del self[first_key]
    return (first_key, value)

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except Exception:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    # Validate cache object
    if not hasattr(cache, 'get') or not hasattr(cache, 'set'):
        raise TypeError("Cache object must provide 'get' and 'set' methods")
    # Validate key
    if key is not None and not callable(key):
        raise TypeError("'key' must be callable")
    # Validate lock
    if lock is not None:
        if not hasattr(lock, '__enter__') or not hasattr(lock, '__exit__'):
            raise TypeError("'lock' must be a context manager")

    def decorator(func):
        def wrapper(self, *args, **kwargs):
            # Compute cache key
            try:
                cache_key = key(self, *args, **kwargs) if key else None
            except Exception:
                # If key function raises, do not cache
                return func(self, *args, **kwargs)

            # Attempt to retrieve from cache
            try:
                if lock:
                    with lock:
                        cached_value = cache.get(cache_key)
                else:
                    cached_value = cache.get(cache_key)
            except Exception:
                cached_value = None

            if cached_value is not None:
                return cached_value

            # Call the original function
            result = func(self, *args, **kwargs)

            # Store the result in cache
            try:
                if lock:
                    with lock:
                        cache.set(cache_key, result)
                else:
                    cache.set(cache_key, result)
            except Exception:
                # Ignore cache set errors
                pass

            return result

        # Preserve original function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """
        Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        # Basic validation
        if not isinstance(file_name, str) or not file_name:
            return None
        if not isinstance(encoding, str) or not encoding:
            return None
        try:
            with open(file_name, 'r', encoding=encoding) as fp:
                return fp.read()
        except Exception:
            return None

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    # Validate input type
    if not isinstance(file_name, str):
        return False
    if not file_name:
        return False
    try:
        with open(file_name, 'rb'):
            return True
    except Exception:
        return False

@classmethod
def _reset_logging(cls):
    """
    Reset
    """
    try:
        import logging
        logging.shutdown()
        root_logger = logging.getLogger()
        for handler in root_logger.handlers[:]:
            root_logger.removeHandler(handler)
        root_logger.setLevel(logging.WARNING)
        logging.Logger.manager.loggerDict.clear()
    except Exception:
        pass

def _getTargetClass(self):
        """
        Define this to return the implementation in use,
        without the 'Py' or 'Fallback' suffix.
        """
        try:
            cls_name = self.__class__.__name__
        except Exception:
            return None
        # Strip out known suffixes used in language bindings
        for suffix in ("Py", "Fallback"):
            if cls_name.endswith(suffix):
                return cls_name[: -len(suffix)]
        # No suffix detected; return the original name
        return cls_name

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ...     ['x', 'y', 'z'],
    ...     ['q', 'z'],
    ...     [1, 3, 5],
    ...     ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not isinstance(orderings, (list, tuple)):
        raise TypeError("orderings must be a list or tuple of orderings")
    adjacency = {}
    indegree = {}
    first_index = {}
    order_counter = 0

    for ordering in orderings:
        try:
            seq = list(ordering)
        except TypeError:
            raise TypeError("Each ordering must be an iterable")
        # check elements are hashable and unique within this ordering
        seen = set()
        for item in seq:
            try:
                hash(item)
            except TypeError:
                raise TypeError(f"Element {item!r} is not hashable")
            if item in seen:
                raise ValueError(f"Duplicate element {item!r} in ordering")
            seen.add(item)
            if item not in adjacency:
                adjacency[item] = set()
            if item not in indegree:
                indegree[item] = 0
            if item not in first_index:
                first_index[item] = order_counter
                order_counter += 1
        # add edges between consecutive elements
        for i in range(len(seq) - 1):
            a, b = seq[i], seq[i + 1]
            if b not in adjacency[a]:
                adjacency[a].add(b)
                indegree[b] = indegree.get(b, 0) + 1
                if b not in first_index:
                    first_index[b] = order_counter
                    order_counter += 1

    # Kahn's algorithm with deterministic priority based on first appearance
    zero_nodes = [node for node, deg in indegree.items() if deg == 0]
    from heapq import heapify, heappush, heappop

    # Use a min-heap keyed by first_index to get deterministic order
    heap = []
    for node in zero_nodes:
        heappush(heap, (first_index[node], node))

    result = []
    seen_in_result = set()

    while heap:
        _, node = heappop(heap)
        if node in seen_in_result:
            continue
        seen_in_result.add(node)
        result.append(node)
        for nbr in adjacency.get(node, []):
            indegree[nbr] -= 1
            if indegree[nbr] == 0:
                heappush(heap, (first_index[nbr], nbr))

    if len(result) != len(adjacency):
        raise ValueError("Orderings contain a cycle or conflict")

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    if classes is None:
        return []
    res = []
    seen = set()
    for c in classes:
        if c in seen:
            continue
        if not isinstance(c, type):
            raise TypeError(f"Expected a class, got {type(c).__name__}")
        # Skip if c is subclass of any already kept base
        is_sub = False
        for base in res:
            try:
                if issubclass(c, base):
                    is_sub = True
                    break
            except TypeError:
                raise TypeError(f"Cannot determine subclass relationship between {c!r} and {base!r}")
        if is_sub:
            continue
        # Remove any previously kept bases that are subclasses of c
        kept = []
        for base in res:
            try:
                if issubclass(base, c):
                    continue
            except TypeError:
                raise TypeError(f"Cannot determine subclass relationship between {base!r} and {c!r}")
            kept.append(base)
        res = kept
        res.append(c)
        seen.add(c)
    return res

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")
    result = []
    try:
        # Iterate over class attributes
        for name, attr in vars(type(self)).items():
            # Skip private/internal names
            if name.startswith('_'):
                continue
            # Skip methods
            if callable(attr):
                continue
            # Get description from doc or __doc__
            description = None
            if isinstance(attr, property):
                description = attr.__doc__
            else:
                description = getattr(attr, '__doc__', None)
                if description is None and hasattr(attr, 'doc'):
                    description = attr.doc
            # Include based on 'all' flag
            if all or description is not None:
                result.append((name, description))
    except Exception:
        # In case of unexpected errors, return what we have so far
        pass
    # Sort by attribute name for consistency
    return sorted(result)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    # If sequence is explicitly None, just return empty result.
    if sequence is None:
        return output
    # If it's a tuple or list, we want to flatten it unless its elements are individual interfaces.
