        # Default assumptions: point is a tuple (coord, val)
        if isinstance(point, (tuple, list)) and len(point) == 2:
            coord, val = point
        else:
            # Try attribute names commonly used for Point objects
            coord = getattr(point, "coordinate", None)
            if coord is None:
                # Fallback: check for 'coords', 'x', 'y', etc.
                if hasattr(point, "coords"):
                    coord = point.coords
                elif hasattr(point, "x") or hasattr(point, "y"):
                    # Attempt to build coordinate from x and y
                    coord = tuple(getattr(point, attr) for attr in ("x", "y") if hasattr(point, attr))
                else:
                    # Cannot determine coordinate
                    coord = None
            val = getattr(point, "value", None)
            if val is None and hasattr(point, "val"):
                val = point.val
            if val is None and hasattr(point, "data"):
                val = point.data
            if coord is None and isinstance(point, (dict,)):
                # For dict: key is coordinate, value is val
                if "coordinate" in point:
                    coord = point["coordinate"]
                if "value" in point:
                    val = point["value"]

