    if len(coordinates) > 0:
        coord_map[coordinates[0]] = 'x'
    if len(coordinates) > 1:
        coord_map[coordinates[1]] = 'y'
    if len(coordinates) > 2:
        coord_map[coordinates[2]] = 'z'

    # Inspect attributes for error fields
    for attr_name in dir(self):
        if not attr_name.startswith('error_'):
            continue

        # Parse attribute name (expected format: error_<coord>_<type>)
        parts = attr_name.split('_', 2)
        if len(parts) < 3:
            continue
        _, coord_name, error_type = parts[0], parts[1], parts[2]

        # Map coordinate to 'x', 'y', or 'z' if applicable
        error_coord = coord_map.get(coord_name, coord_name)

        # Build the key used in the context error mapping
        ctx_key = f"{error_coord}_{error_type}"

        # Retrieve the attribute value
        try:
            value = getattr(self, attr_name)
        except Exception:
            continue

        # Determine indices of errors
        indices = []
        try:
            # If the value is an iterable (e.g., list/array of indices or error values)
            if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
                for idx, val in enumerate(value):
                    # Consider non‑None, non‑zero values as indicative of an error
                    if val is not None and val:
                        indices.append(idx)
            # If the value itself is an integer or float, treat it as a single index
            elif isinstance(value, (int, float)):
                indices.append(int(value))
            # If the value is a dict with an 'index' key (common in some graph frameworks)
            elif isinstance(value, dict) and 'index' in value:
                indices.append(int(value['index']))
        except Exception:
            pass

        # If indices were found, add to the error context
        if indices:
            # In case of multiple indices, store them as a list; otherwise, just store the single value
            stored_value = {"index": indices[0]} if len(indices) == 1 else {"index": indices}
            # Preserve any pre‑existing entry for the same key by merging
            if ctx_key in error_context:
                existing = error_context[ctx_key]
                if isinstance(existing, dict) and 'index' in existing:
                    existing_idx = existing['index']
                    # Combine single values into a list
                    if not isinstance(existing_idx, list):
                        existing_idx = [existing_idx]
                    if isinstance(stored_value['index'], list):
                        existing_idx.extend(stored_value['index'])
                    else:
                        existing_idx.append(stored_value['index'])
                    error_context[ctx_key]['index'] = existing_idx
            else:
                error_context[ctx_key] = stored_value

    # Nothing to return; the context dict is mutated in place.

