            errors.append({str(key): "expected string or bytes-like object"})
        else:
            if not re.fullmatch(KEY_REGEX, key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex {KEY_REGEX}"}
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            # For bytes, decode to string for regex matching
            if isinstance(value, bytes):
                try:
                    vs = value.decode()
                except UnicodeDecodeError:
                    errors.append({str(value): "expected string or bytes-like object"})
                    continue
            else:
                vs = value
            if not re.fullmatch(VALUE_REGEX, vs):
                errors.append(
                    {value: f"Label value '{vs}' does not match the regex {VALUE_REGEX}"}
                )

    if errors:
        raise ValidationError(errors)

