    """
    # Basic type and existence checks
    if prior is None:
        raise ValueError("prior cannot be None.")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}.")

    # Retrieve inventory containers (attributes or dicts)
    try:
        self_inventory = getattr(self, "inventory")
    except AttributeError as exc:
        raise ValueError("Current instance must have an 'inventory' attribute.") from exc

    try:
        prior_inventory = getattr(prior, "inventory")
    except AttributeError as exc:
        raise ValueError("Prior instance must have an 'inventory' attribute.") from exc

    # Functions to get value from dicts or objects
    def _get(attr_obj, names):
        for name in names:
            if isinstance(attr_obj, dict) and name in attr_obj:
                return attr_obj[name]
            if hasattr(attr_obj, name):
                return getattr(attr_obj, name)
        return None

    # Identify inventory (e.g., id, uuid, name)
    self_id = _get(self_inventory, ("id", "uuid", "name"))
    prior_id = _get(prior_inventory, ("id", "uuid", "name"))

    if self_id is None or prior_id is None:
        raise ValueError("Both inventories must expose an identifier (id/uuid/name).")

    if self_id != prior_id:
        raise ValueError("Inventory identifiers do not match; cannot validate prior version.")

    # Retrieve versions
    self_version = _get(self_inventory, ("version", "ver", "rev"))
    prior_version = _get(prior_inventory, ("version", "ver", "rev"))

    if self_version is None or prior_version is None:
        raise ValueError("Both inventories must expose a numeric version value.")

    if not isinstance(self_version, (int, float)) or not isinstance(prior_version, (int, float)):
        raise TypeError("Inventory versions must be numeric.")

    # Ensure prior is indeed older
    if prior_version >= self_version:
        raise ValueError("Prior inventory must have a lower version number than the current inventory.")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for a given version in inventory.

    The inventory is expected to be a mapping of version numbers to state mappings.
    Each state mapping should itself be a mapping of logical paths to a list or single
    content file path. The returned dictionary maps each logical path to a set
    of content files.  For the requested *version*, all content files from that
    version *and* from later versions that refer to the same logical path are
    included in the resultant set.

    Parameters
    ----------
    inventory : dict
        A dictionary where the keys are version identifiers (int or coercible to
        int) and the values are state dictionaries mapping logical paths to
        content file(s).  Example::

            {
                1: {'/foo': ['file1', 'file2'], '/bar': 'file3'},
                2: {'/foo': ['file4'], '/baz': 'file5'}
            }

    version : int or str
        The version whose logical path map is required.  The value is coerced
        to an integer; a ``ValueError`` is raised if this fails.

    Returns
    -------
    dict
        Mapping of logical path -> set of content file paths for the requested
        version.  Duplicate file paths are collapsed by the set.

    Raises
    ------
    TypeError
        If *inventory* is not a dictionary.
    ValueError
        If *version* cannot be coerced to an integer or if the requested
        version does not exist in *inventory*.
    """
    # Basic input validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")

    try:
        target_ver = int(version)
    except Exception as exc:
        raise ValueError(f"version must be convertible to an integer, got {version!r}") from exc

    if target_ver not in inventory:
        raise ValueError(f"Requested version {target_ver} not found in inventory")

    # Build the map by scanning all versions >= target_ver
    result = {}
    try:
        for ver in sorted(inventory.keys()):
            # Skip any non‑numeric version keys
            try:
                ver_int = int(ver)
            except Exception:
                continue
            if ver_int < target_ver:
                continue

            state_map = inventory[ver]
            if not isinstance(state_map, dict):
                continue

            for logical_path, files in state_map.items():
                if logical_path not in result:
                    result[logical_path] = set()

                # Accept a single file or an iterable of files
                if isinstance(files, (list, tuple, set)):
                    for f in files:
                        result[logical_path].add(str(f))
                else:
                    result[logical_path].add(str(files))
    except Exception as exc:
        # General catch to avoid leaking internal structure
        raise RuntimeError("Error while building logical path map") from exc

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic validation of input types
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, set, or tuple")

    # The fixity block must contain a 'files' key pointing to an iterable
    if "files" not in fixity:
        raise ValueError("fixity block missing required 'files' key")
    files_collection = fixity["files"]
    if not isinstance(files_collection, (list, tuple)):
        raise ValueError("'files' key in fixity block must reference a list or tuple")

    # Convert manifest to a set for fast lookup
    manifest_set = set(manifest_files)
    seen_paths = set()

    required_keys = {"path", "checksum", "size", "digest_algorithm"}
    for idx, file_entry in enumerate(files_collection):
        if not isinstance(file_entry, dict):
            raise ValueError(f"File entry at index {idx} is not a dictionary")
        missing = required_keys - file_entry.keys()
        if missing:
            raise ValueError(f"File entry at index {idx} missing keys: {', '.join(missing)}")

        path = file_entry["path"]
        if not isinstance(path, str) or not path:
            raise ValueError(f"Invalid 'path' value in file entry at index {idx}")
        if path not in manifest_set:
            raise ValueError(f"Path '{path}' referenced in fixity not found in manifest")
        if path in seen_paths:
            raise ValueError(f"Duplicate path '{path}' found in fixity block")
        seen_paths.add(path)

        checksum = file_entry["checksum"]
        if not isinstance(checksum, str) or not checksum:
            raise ValueError(f"Invalid 'checksum' for path '{path}'")

        size = file_entry["size"]
        if not isinstance(size, int) or size < 0:
            raise ValueError(f"Invalid 'size' for path '{path}', must be non‑negative integer")

        algo = file_entry["digest_algorithm"]
        if not isinstance(algo, str) or not algo:
            raise ValueError(f"Invalid 'digest_algorithm' for path '{path}'")

    return True

def files_list(path):
    """
    Return the files in `path`.
    """
    os = __import__('os')
    if not isinstance(path, (str, bytes)) and not hasattr(path, '__fspath__'):
        raise TypeError("path must be a string, bytes, or path-like object")
    try:
        entries = os.listdir(path)
    except OSError as e:
        raise RuntimeError(f"Could not list directory '{path}': {e}") from e
    files = []
    for entry in entries:
        full = os.path.join(path, entry)
        if os.path.isfile(full):
            files.append(entry)
    return files

def select_filenames_by_prefix(prefix, files):
    """
    Get files which belongs to a document package.

    Retorna os arquivos da lista `files` cujos nomes iniciam com `prefix`

    Parameters
    ----------
    prefix : str
        Filename prefix
    files : str list
        Files paths
    Returns
    -------
    list
        files paths which basename files matches to prefix
    """
    # Validate input types
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    if not hasattr(files, '__iter__'):
        raise TypeError("files must be an iterable of file paths")

    # Attempt to import os for reliable basename extraction
    try:
        import os
    except Exception:
        os = None

    matched_files = []
    for f in files:
        # Skip non-string entries
        if not isinstance(f, str):
            continue
        try:
            # Use os.path.basename if available, otherwise fallback to split
            if os and hasattr(os.path, 'basename'):
                basename = os.path.basename(f)
            else:
                # Split on both types of path separators
                sep_candidates = ('/', '\\')
                for sep in sep_candidates:
                    if sep in f:
                        basename = f.split(sep)[-1]
                        break
                else:
                    basename = f  # No separator found
            if basename.startswith(prefix):
                matched_files.append(f)
        except Exception:
            # Ignore individual errors and continue
            continue

    return matched_files

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    try:
        import os

        if not isinstance(folder, str):
            return {}

        if not os.path.isdir(folder):
            return {}

        data = {}
        for root, dirs, files in os.walk(folder):
            # Find all XML files in the current directory
            xml_files = [f for f in files if f.lower().endswith('.xml')]
            if not xml_files:
                continue

            # Compute relative directory name from the root folder
            rel_dir = os.path.relpath(root, folder)
            # Normalize '.' to empty string for root level
            if rel_dir == '.':
                rel_dir = ''

            for xml_file in xml_files:
                base_name, _ = os.path.splitext(xml_file)
                # Collect all files in this directory that share the same base name
                related_files = []
                for f in files:
                    if os.path.splitext(f)[0] == base_name:
                        # Build relative path for each related file
                        if rel_dir:
                            rel_path = os.path.join(rel_dir, f)
                        else:
                            rel_path = f
                        related_files.append(rel_path)

                # Build key for the dictionary
                key = os.path.join(rel_dir, base_name) if rel_dir else base_name
                data[key] = related_files

        return data
    except Exception:
        # In case of any unexpected error, return an empty dict
        return {}

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    try:
        if not isinstance(content, str):
            raise TypeError("content must be a string")
        return content.replace('w:st="', 'w-st="')
    except Exception as exc:
        raise ValueError(f"Error while fixing namespace prefix: {exc}") from exc

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None

    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
        except Exception:
            continue  # Invalid xpath or evaluation error

        if not matches:
            continue  # No result for this xpath

        first = matches[0]
        # If the match is a string, return it stripped
        if isinstance(first, str):
            return first.strip()
        # If it's an element-like object, try to get its text content
        text = None
        if hasattr(first, "text"):
            text = getattr(first, "text")
        if text is not None:
            return text.strip() if isinstance(text, str) else text

    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    The representation is produced recursively for nested containers
    and objects that provide a :py:meth:`pretty` method. The
    ``indent`` parameter controls the number of spaces used for each
    nesting level and to avoid infinite recursion, already visited
    objects are replaced by the string ``"<circular ref>"``.
    When ``debug`` is ``True`` type information is appended after
    each value where relevant.

    Returns
    -------
    str
        A human‑readable representation of ``self``.
    """
    # Guard against nonsensical indent values
    try:
        indent = int(indent)
    except Exception:
        indent = 0
    if indent < 0:
        indent = 0

    # Helper to escape strings
    def _repr_str(s):
        return repr(s)

    # Tracker for circular references
    _seen = set()

    def _pretty(obj, level):
        obj_id = id(obj)
        if obj_id in _seen:
            return "<circular ref>"
        _seen.add(obj_id)

        prefix = " " * (level * indent)

        # Primitive types
        if obj is None:
            return "None" + (f"  # <class 'NoneType'>" if debug else "")
        if isinstance(obj, (int, float, complex, bool)):
            return repr(obj) + (f"  # <class '{type(obj).__name__}'>"
                                if debug else "")
        if isinstance(obj, str):
            return _repr_str(obj) + (f"  # <class 'str'>"
                                    if debug else "")

        # Containers
        if isinstance(obj, (list, tuple, set, frozenset)):
            opening = "[" if isinstance(obj, list) else (
                "(" if isinstance(obj, tuple) else ("{" if isinstance(obj, set) else "{"))
            closing = "]" if isinstance(obj, list) else (
                ")" if isinstance(obj, tuple) else ("}" if isinstance(obj, set) else "}")
            inner = []
            for idx, item in enumerate(obj):
                inner.append(_pretty(item, level + 1))
            joined = ",\n".join(" " * ((level + 1) * indent) + i for i in inner)
            return f"{opening}\n{joined}\n{prefix}{closing}" if inner else f"{opening}{closing}"

        if isinstance(obj, dict):
            inner = []
            for k, v in obj.items():
                key_repr = (
                    _repr_str(k) if isinstance(k, str) else _pretty(k, 0)
                )
                val_repr = _pretty(v, level + 1)
                inner.append(f"{key_repr}: {val_repr}")
            joined = ",\n".join(" " * ((level + 1) * indent) + i for i in inner)
            return f"{{\n{joined}\n{prefix}}}" if inner else "{}"

        # Objects with a custom pretty method
        if hasattr(obj, "pretty") and callable(getattr(obj, "pretty")):
            try:
                return obj.pretty(indent, debug)
            except Exception:
                # Fallback to __repr__
                pass

        # Fallback: use __dict__ if available
        if hasattr(obj, "__dict__"):
            attrs = vars(obj)
            if attrs:
                inner = []
                for k, v in attrs.items():
                    val_repr = _pretty(v, level + 1)
                    inner.append(f"{k}={val_repr}")
                joined = ",\n".join(" " * ((level + 1) * indent) + i for i in inner)
                return f"{obj.__class__.__name__}(\n{joined}\n{prefix})"
            else:
                return f"{obj.__class__.__name__}()"

        # Fallback to repr
        return repr(obj)

    return _pretty(self, 0)

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified hook.
    """
    if hook is None:
        raise ValueError("hook cannot be None")
    # Ensure a registry exists on the instance
    if not hasattr(self, "_registry") or not isinstance(self._registry, dict):
        self._registry = {}
    def decorator(func):
        if not callable(func):
            raise TypeError("Handler must be callable")
        listeners = self._registry.setdefault(hook, [])
        listeners.append(func)
        return func
    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    # Get the raw name from the provided function
    try:
        name = namefunc()
    except Exception as exc:
        # Propagate any exception from namefunc
        raise exc

    # In Python 2 'unicode' type exists; in Python 3 it does not.
    # We want to return a bytestring. If the result is a unicode object
    # (Python 2) or a str object (Python 3, representing unicode),
    # we encode it to UTF‑8 bytes. Otherwise we assume it is already a
    # bytes object and return it unchanged.
    try:
        # Python 2 path
        if isinstance(name, unicode):
            return name.encode('utf-8')
    except NameError:
        # Python 3 path – unicode is not defined, 'str' is unicode.
        if isinstance(name, str):
            return name.encode('utf-8')

    # If we reach here, name is already a bytes-like object
    return name

def get_versions():
    """Get version information or return default if unable to do so."""
    result = {}
    # Primary attempt: use importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError

        # Guess the top‑level package name from the current module
        top_level = __name__.split('.')[0]
        try:
            result['version'] = version(top_level)
        except PackageNotFoundError:
            # If the package is not installed, fall back to environment variable or git
            result['version'] = None

        # Attempt to get full revision ID (e.g., commit hash) via git
        if result.get('version') is None:
            import subprocess, os
            cwd = os.path.dirname(__file__)
            try:
                rev = subprocess.check_output(
                    ["git", "rev-parse", "HEAD"],
                    cwd=cwd,
                    stderr=subprocess.DEVNULL,
                    text=True,
                ).strip()
                result['full-revisionid'] = rev
                # Use a generic version string when we cannot get a tag
                result['version'] = "0+unknown"
            except Exception:
                pass
    except Exception:
        # importlib.metadata might not be available or operation may fail
        result = {}

    # Fallback: try to read a VERSION file in the same directory
    if not result.get('version'):
        try:
            import os
            ver_file = os.path.join(os.path.dirname(__file__), 'VERSION')
            with open(ver_file, 'r', encoding='utf-8') as f:
                result['version'] = f.read().strip()
        except Exception:
            pass

    # Ensure dictionary has both keys
    if 'version' not in result or not result['version']:
        result['version'] = '0+unknown'
    if 'full-revisionid' not in result:
        result['full-revisionid'] = ''

    return result

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters:
        pieces (dict | list | tuple): Collection of version components.
            - dict must contain 'major', 'minor', 'patch' keys (integers). Optional
              'prerelease' and 'build' string keys are allowed.
            - list/tuple must have at least three items: major, minor, patch (integers).
              Optional fourth and fifth items are prerelease and build strings.
        style (str): Rendering style. Supported values are:
            - 'semver': Semantic Versioning format e.g. "1.2.3-alpha+001".
            - 'raw': Raw string representation of the input object.

    Returns:
        str: Rendered version string.

    Raises:
        ValueError: If inputs are invalid or style unknown.
    """
    # Validate style
    if not isinstance(style, str):
        raise ValueError('style must be a string')
    style = style.lower()

    # Normalize pieces into components
    if isinstance(pieces, dict):
        try:
            major = pieces['major']
            minor = pieces['minor']
            patch = pieces['patch']
        except KeyError as exc:
            raise ValueError(f"Missing required key in pieces dict: {exc}") from None
        prerelease = pieces.get('prerelease')
        build = pieces.get('build')
    elif isinstance(pieces, (list, tuple)):
        if len(pieces) < 3:
            raise ValueError('pieces list/tuple must contain at least major, minor, and patch')
        major, minor, patch = pieces[0], pieces[1], pieces[2]
        prerelease = pieces[3] if len(pieces) > 3 else None
        build = pieces[4] if len(pieces) > 4 else None
    else:
        raise ValueError('pieces must be a dict or list/tuple')

    # Validate numeric components
    for name, val in (('major', major), ('minor', minor), ('patch', patch)):
        if not isinstance(val, int) or val < 0:
            raise ValueError(f"{name} must be a non‑negative integer")

    # Validate optional string components
    if prerelease is not None and not isinstance(prerelease, str):
        raise ValueError('prerelease must be a string')
    if build is not None and not isinstance(build, str):
        raise ValueError('build must be a string')

    # Render according to chosen style
    if style == 'semver':
        version = f"{major}.{minor}.{patch}"
        if prerelease:
            version += f"-{prerelease}"
        if build:
            version += f"+{build}"
        return version
    elif style == 'raw':
        # For raw rendering, simply return a string representation
        return str(pieces)
    else:
        raise ValueError(f"unknown style '{style}'")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        raise ValueError("pieces cannot be None")
    try:
        for item in pieces:
            if isinstance(item, str) and '+' in item:
                return '.'
        return '+'
    except Exception as e:
        raise ValueError(f"Invalid input for pieces: {e}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    import sys

    # Normalize commands to a list of command strings
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        # Ensure each element is a string
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    # arguments for each command (assumed same for all commands if provided)
    if args is None:
        args_list = []
    else:
        if isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            raise TypeError("args must be None or a list/tuple of strings")

    results = []

    for cmd in cmd_list:
        # Build the full command string with quoted args if using shell
        if args_list:
            quoted_args = " ".join(shlex.quote(str(a)) for a in args_list)
            full_cmd = f"{cmd} {quoted_args}"
        else:
            full_cmd = cmd

        if verbose:
            print(f"Running: {full_cmd}")

        try:
            proc = subprocess.run(
                full_cmd,
                shell=True,
                cwd=cwd,
                capture_output=True,
                text=True,
                env=env,
                stderr=subprocess.DEVNULL if hide_stderr else None,
            )
        except Exception as exc:
            raise RuntimeError(f"Execution of command '{full_cmd}' failed: {exc}") from exc

        if verbose:
            print(f"Return code: {proc.returncode}")
            if not hide_stderr and proc.stderr:
                sys.stderr.write(proc.stderr)

        results.append({
            'command': cmd,
            'returncode': proc.returncode,
            'stdout': proc.stdout,
            'stderr': None if hide_stderr else proc.stderr,
        })

    return results

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to retrieve a collection of objects that represent the hierarchy.
    # The attribute names are guessed; fall back to an empty iterable if not found.
    objects = getattr(self, 'objects', None) or getattr(self, '_objects', None) or getattr(self, 'root_objects', None) \
              or getattr(self, 'root', None) or getattr(self, 'hierarchy', None)

    # Normalize to an iterable of objects
    if isinstance(objects, dict):
        objects = objects.values()
    if not hasattr(objects, '__iter__'):
        # Unable to iterate; treat as no objects
        objects = []

    for obj in objects:
        num_objects += 1
        is_valid = True
        try:
            if validate_objects:
                if hasattr(obj, 'is_valid') and callable(obj.is_valid):
                    is_valid = bool(obj.is_valid())
                elif hasattr(obj, 'valid'):
                    is_valid = bool(obj.valid)
                else:
                    # If no explicit validation method, assume object is valid
                    is_valid = True
        except Exception as e:
            is_valid = False
            if show_warnings:
                print(f"Warning: Object {obj!r} validation raised exception: {e}")

        if is_valid and check_digests:
            try:
                if hasattr(obj, 'check_digest') and callable(obj.check_digest):
                    digest_ok = bool(obj.check_digest())
                elif hasattr(obj, 'verify_digest') and callable(obj.verify_digest):
                    digest_ok = bool(obj.verify_digest())
                else:
                    # Assume digest verified if no method
                    digest_ok = True
            except Exception as e:
                digest_ok = False
                if show_warnings:
                    print(f"Warning: Object {obj!r} digest check raised exception: {e}")
            if not digest_ok:
                is_valid = False

        if is_valid:
            good_objects += 1
        elif show_warnings:
            print(f"Warning: Object {obj!r} failed validation.")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not isinstance(version, str) or not version or not version.isdigit():
            raise ValueError("Invalid version format: must be a non-empty numeric string")
        num = int(version)
        new_num = num + 1

        # Preserve leading zeros if the original version had them
        original_length = len(version)
        if new_num < 10 ** original_length:
            return str(new_num).zfill(original_length)
        else:
            # If the incremented number has more digits, just return it plain
            return str(new_num)
    except Exception as e:
        raise ValueError(f"Error computing next version: {e}") from e

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        import re

        if not os.path.exists(path):
            return f"Path does not exist: {path}"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            entries = os.listdir(path)
            # If there is a "0=*" file, this directory is at least an OCFL
            # container (object or root).
            if "0=*" in entries:
                # Check for subdirectories that match OCFL object ID pattern
                # (7 hexadecimal characters, case-insensitive).
                subdirs = [
                    d for d in entries
                    if os.path.isdir(os.path.join(path, d))
                ]
                if any(re.fullmatch(r"[0-9a-fA-F]{7}", d) for d in subdirs):
                    # Presence of such named subdirectories indicates a storage root.
                    return "root"
                else:
                    # Otherwise, this is an object directory.
                    return "object"
            else:
                # No inventory file; could be an empty or unrelated directory.
                return "unknown directory"

        return f"Unsupported path type: {path}"

    except Exception as e:
        # Provide the exception message as the error description.
        return f"Error: {e}"

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, Node) tuples that may contain duplicate keys.
    """
    from collections import OrderedDict

    # Simple check to ensure nodes is iterable of tuples of length 2
    if not isinstance(nodes, (list, tuple)):
        raise TypeError("nodes must be a list or tuple of (ScalarNode, Node) pairs")
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("each element in nodes must be a tuple (ScalarNode, Node)")

    def merge_mapping_nodes(node1, node2):
        """Deep merge two MappingNode objects, returning a new MappingNode."""
        # Using the tag from the first node for consistency
        tag = node1.tag if hasattr(node1, "tag") else node1[1]
        # Convert mapping values to ordered dicts keyed by scalar value
        mapping1 = OrderedDict()
        mapping2 = OrderedDict()
        for k, v in node1.value:
            mapping1[k.value] = (k, v)
        for k, v in node2.value:
            mapping2[k.value] = (k, v)

        merged = OrderedDict()
        # Preserve order of first occurrence of keys
        for key, kv in mapping1.items():
            merged[key] = kv
        for key, kv in mapping2.items():
            if key in merged:
                # Merge recursively if both values are MappingNode
                existing_k, existing_v = merged[key]
                if hasattr(existing_v, "tag") and hasattr(kv[1], "tag"):
                    if 'map' in getattr(existing_v, "tag", "") and 'map' in getattr(kv[1], "tag", ""):
                        merged[key] = (existing_k, merge_mapping_nodes(existing_v, kv[1]))
                    else:
                        # scalar overwrite
                        merged[key] = (existing_k, kv[1])
                else:
                    merged[key] = (existing_k, kv[1])
            else:
                merged[key] = kv

        merged_list = [(k, v) for (_, (k, v)) in merged.items()]
        return type(node1)(tag=tag, value=merged_list)

    merged = OrderedDict()
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_value = merged[key][1]
            if hasattr(existing_value, "tag") and hasattr(value_node, "tag"):
                if 'map' in getattr(existing_value, "tag", "") and 'map' in getattr(value_node, "tag", ""):
                    # Both are MappingNode; merge recursively
                    merged[key] = (merged[key][0], merge_mapping_nodes(existing_value, value_node))
                else:
                    # Override with last value
                    merged[key] = (merged[key][0], value_node)
            else:
                merged[key] = (merged[key][0], value_node)
        else:
            merged[key] = (key_node, value_node)

    return [(k, v) for (_, (k, v)) in merged.items()]

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.
    """
    # Ensure the argument is a valid ArgumentParser instance.
    try:
        import argparse
    except ImportError:
        raise ImportError("argparse module is required for parser_flags to work.")
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("Expected an argparse.ArgumentParser instance, got %r" % type(parser))

    # Extract all option strings from the parser's actions.
    flags = []
    for action in getattr(parser, "_actions", []):
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)

    # Return the flags as a space-separated string; return an empty string if none.
    return " ".join(flags) if flags else ""

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    # Ensure we are always working with a list of arguments
    args = list(unparsed_arguments)

    # Create a base parser.  We don't know the exact options, so we will let argparse
    # parse what it can and store the rest as unknown.
    parser = argparse.ArgumentParser(add_help=False)
    try:
        namespace, unknown = parser.parse_known_args(args)
    except Exception as e:
        # If argparse fails, fall back to an empty namespace
        namespace = argparse.Namespace()
    # Return a mapping; we don't have subparser support in this generic version,
    # so we always use the "global" key.
    return {"global": namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    import collections
    # Basic input validation
    if not isinstance(subparsers, collections.abc.Mapping):
        raise TypeError("subparsers must be a mapping from name to argparse.ArgumentParser")
    if not isinstance(unparsed_arguments, collections.abc.Sequence):
        raise TypeError("unparsed_arguments must be a sequence of strings (like list or tuple)")

    parsed_namespaces = {}
    # Store the set of unclaimed arguments for each parser
    remaining_sets = []

    for name, parser in subparsers.items():
        # Ensure the parser is an ArgumentParser instance
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except argparse.ArgumentError as exc:
            raise ValueError(f"Argument parsing failed for subparser '{name}': {exc}") from exc
        except SystemExit as exc:
            # argparse may call sys.exit on parse errors; convert to exception instead
            raise ValueError(f"Argument parsing failed for subparser '{name}': {exc}") from exc
        except Exception as exc:
            raise RuntimeError(f"Unexpected error while parsing subparser '{name}': {exc}") from exc

        parsed_namespaces[name] = namespace
        remaining_sets.append(set(remaining))

    # Compute arguments not claimed by any subparser
    if not remaining_sets:
        not_claimed = list(unparsed_arguments)
    else:
        not_claimed = [arg for arg in unparsed_arguments
                       if all(arg in rem_set for rem_set in remaining_sets)]

    return parsed_namespaces, not_claimed

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise ValueError("parser argument cannot be None")
    try:
        actions = getattr(parser, "actions", None)
        if actions is None:
            # Some older argparse implementations may use _actions
            actions = getattr(parser, "_actions", [])
    except Exception:
        raise ValueError("The provided object does not appear to be an argparse.ArgumentParser")
    if not isinstance(actions, (list, tuple)):
        raise ValueError("Unable to retrieve actions from the parser")
    flags = []
    for action in actions:
        # Skip positional arguments (no option_strings)
        opt_strings = getattr(action, "option_strings", [])
        if isinstance(opt_strings, (list, tuple)):
            flags.extend(opt_strings)
    # Remove duplicates while preserving order
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)
    return " ".join(unique_flags) if unique_flags else ""

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input parameters
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an integer, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError(f"max_results must be a positive integer, got {max_results}")

    # Generator that yields pages of the specified maximum size
    def _page_generator():
        for start in range(0, len(response), max_results):
            # Slicing handles cases where max_results extends past the list's end
            yield response[start:start + max_results]

    return _page_generator()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable ``dicts``.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not hasattr(dicts, "__iter__"):  # pragma: no cover
        raise TypeError("The argument must be an iterable of dictionaries")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("All elements of the iterable must be dictionaries")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(
                    f"Dictionary values must be numeric, got {type(value)} for key {key}"
                )
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    import re
    # Validate input types
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    # Pattern matches :key or {key}
    pattern = re.compile(r':(\w+)|\{(\w+)\}')

    def _replacer(match):
        # Extract the placeholder name from the match groups
        key = match.group(1) or match.group(2)
        if key not in url_args:
            raise KeyError(f"URL argument '{key}' not provided")
        # Convert the argument value to string (handles other types)
        return str(url_args[key])

    # Perform the replacement and return the updated URL
    return pattern.sub(_replacer, url)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    import argparse
    # Validate the input type
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    try:
        for action in parser._actions:
            # action.option_strings may not exist for some actions (e.g., positional)
            option_strings = getattr(action, "option_strings", None)
            if option_strings:
                # Flatten the list of option strings
                flags.extend(option_strings)
    except Exception as exc:
        # Any runtime issues during flag extraction are wrapped in a ValueError
        raise ValueError(f"Failed to extract flags from parser: {exc}") from exc

    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    try:
        if not isinstance(number, int):
            raise TypeError("number must be an integer")
        if number < 0:
            raise ValueError("number must be non-negative")
        if not isinstance(alphabet, (list, tuple)) or len(alphabet) < 2:
            raise ValueError("alphabet must be a list/tuple with at least two symbols")
        for sym in alphabet:
            if not isinstance(sym, str):
                raise TypeError("alphabet elements must be strings")

        base = len(alphabet)
        if number == 0:
            result = alphabet[0]
        else:
            digits = []
            n = number
            while n > 0:
                n, rem = divmod(n, base)
                digits.append(alphabet[rem])
            result = ''.join(reversed(digits))

        if padding is not None:
            if not isinstance(padding, int):
                raise TypeError("padding must be an integer or None")
            if padding < 0:
                raise ValueError("padding must be non-negative")
            if padding > len(result):
                result = alphabet[0] * (padding - len(result)) + result

        return result
    except Exception as e:
        raise e

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    # Validate input types
    if not isinstance(value, str):
        raise TypeError("The 'value' parameter must be a string.")
    # Ensure the replacement argument is a string
    if not isinstance(arg, str):
        try:
            arg = str(arg)
        except Exception as exc:
            raise TypeError("The 'arg' parameter cannot be converted to a string.") from exc
    # Perform the replacement with exception handling
    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise RuntimeError("An error occurred while replacing '.' characters.") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    result = set()
    def _rec(c):
        try:
            for sub in c.__subclasses__():
                if sub not in result:
                    result.add(sub)
                    _rec(sub)
        except Exception:
            # In case of special types that raise errors when inspecting subclasses
            pass
    _rec(cls)
    return result

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Expected a dict, got %r" % type(item))
    result = {}
    for key, value in item.items():
        # Only convert keys that contain wildcard characters
        if isinstance(key, str) and ('*' in key or '?' in key):
            regex_parts = []
            for ch in key:
                if ch == '*':
                    regex_parts.append('.*')
                elif ch == '?':
                    regex_parts.append('.')
                else:
                    regex_parts.append(re.escape(ch))
            regex_key = '^' + ''.join(regex_parts) + '$'
        else:
            regex_key = key
        result[regex_key] = value
    return result

import re
def unquote(name):
    """Remove quote from the given name."""
    try:
        if name is None:
            return None
        if not isinstance(name, str):
            raise TypeError(f"unquote expects a string, got {type(name).__name__}")
        # Strip any leading or trailing single or double quotes
        return re.sub(r"^[\'\"]|[\'\"]$", "", name)
    except Exception as e:
        raise ValueError(f"Failed to unquote '{name}': {e}") from e

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os, shlex
    if not isinstance(s, str):
        raise TypeError(f's must be a string, got {type(s).__name__}')
    if platform == 'this':
        platform = 1 if os.name != 'nt' else 0
    try:
        if platform == 1:
            # POSIX-style splitting
            return shlex.split(s, posix=True)
        elif platform == 0:
            # Windows/CMD-style splitting
            return shlex.split(s, posix=False)
        else:
            raise ValueError(f'Unsupported platform value: {platform!r}')
    except Exception as exc:
        raise ValueError(f'Failed to split command: {exc}') from exc

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Import modules locally to avoid polluting namespace
    try:
        from pathlib import Path
        import shutil
        import uuid
        import os
    except Exception as exc:
        raise RuntimeError(f"Failed to import required modules: {exc}") from exc

    # Validate archive_path
    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive path does not exist or is not a file: {archive_path}")

    # Resolve tmp_path
    tmp_dir = Path(tmp_path)
    try:
        tmp_dir = tmp_dir.resolve()
    except Exception as exc:
        raise RuntimeError(f"Failed to resolve temporary path '{tmp_path}': {exc}") from exc

    if not tmp_dir.is_dir():
        # Try to create the temp directory if it doesn't exist
        try:
            tmp_dir.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            raise PermissionError(f"Cannot create temporary directory '{tmp_path}': {exc}") from exc

    # Ensure tmp_dir is writable
    if not os.access(tmp_dir, os.W_OK):
        raise PermissionError(f"Temporary directory '{tmp_path}' is not writable.")

    # Create a unique extraction directory
    extract_dir_name = f"repo_{uuid.uuid4().hex}"
    extract_dir = tmp_dir / extract_dir_name
    try:
        extract_dir.mkdir(parents=True, exist_ok=False)
    except Exception as exc:
        raise RuntimeError(f"Could not create extraction directory '{extract_dir}': {exc}") from exc

    # Unpack the archive
    try:
        shutil.unpack_archive(str(archive), str(extract_dir))
    except shutil.ReadError as exc:
        # Could be unsupported format or corrupted archive
        # Clean up partially extracted files
        try:
            shutil.rmtree(str(extract_dir))
        except Exception:
            pass
        raise ValueError(f"Failed to unpack archive '{archive_path}': unsupported format or corrupted file.") from exc
    except Exception as exc:
        # General extraction error
        try:
            shutil.rmtree(str(extract_dir))
        except Exception:
            pass
        raise RuntimeError(f"Failed to unpack archive '{archive_path}': {exc}") from exc

    # Determine repository root directory. If the archive produced a single top‑level folder,
    # use that folder as the repo root; otherwise use the extraction directory itself.
    try:
        entries = [p for p in extract_dir.iterdir() if p.is_dir() or p.is_file()]
        if len(entries) == 1 and entries[0].is_dir():
            repo_root = entries[0]
        else:
            repo_root = extract_dir
    except Exception as exc:
        # Cleanup on failure
        try:
            shutil.rmtree(str(extract_dir))
        except Exception:
            pass
        raise RuntimeError(f"Could not determine repository root: {exc}") from exc

    # Construct a file URL suitable for use as a git remote origin
    repo_url = f"file://{repo_root.resolve().as_posix()}"

    return repo_url

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    # Handle None or sentinel values
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")
    freq = frequency.strip().lower()
    if freq == "always":
        return None
    if not freq:
        raise ValueError("Empty frequency string")

    parts = freq.split()
    if len(parts) < 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'")

    # Parse numeric part
    num_part = parts[0]
    try:
        number = int(num_part)
    except ValueError:
        try:
            number = float(num_part)
        except ValueError:
            raise ValueError(f"Frequency number is not a valid int or float: '{num_part}'")

    # Parse unit part (join any remaining parts in case of multi-word units)
    unit_part = " ".join(parts[1:]).strip()

    # Mapping from unit string to timedelta keyword argument
    unit_map = {
        "second": "seconds",
        "seconds": "seconds",
        "minute": "minutes",
        "minutes": "minutes",
        "hour": "hours",
        "hours": "hours",
        "day": "days",
        "days": "days",
        "week": "weeks",
        "weeks": "weeks",
    }

    if unit_part not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: '{unit_part}'")

    # Build timedelta kwargs
    kwargs = {unit_map[unit_part]: number}
    try:
        return datetime.timedelta(**kwargs)
    except Exception as exc:
        raise ValueError(f"Failed to create timedelta from frequency '{frequency}': {exc}") from exc

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    host = host.strip()

    # Direct hostname check
    if host.lower() == "localhost":
        return True

    # If host contains a port (e.g., "localhost:8080") strip it
    if ":" in host and not host.startswith("["):
        host = host.split(":", 1)[0]
    elif host.startswith("["):
        # IPv6 address might be in [addr]:port form
        try:
            host = host.split("]")[0][1:]  # strip the brackets
        except Exception:
            pass

    # Try resolving host to its IP addresses
    try:
        # Resolve without specifying service port; keep any family (IPv4/IPv6)
        addrinfo_list = socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
        for addrinfo in addrinfo_list:
            family, _, _, _, sockaddr = addrinfo
            ip = sockaddr[0]
            # IPv4 loopback
            if family == socket.AF_INET:
                if ip.startswith("127."):
                    return True
            # IPv6 loopback
            elif family == socket.AF_INET6:
                # Normalize IPv6 address to canonical form
                if ip.lower() in ("::1", "0:0:0:0:0:0:0:1"):
                    return True
    except socket.gaierror:
        # Host could be an IP literal that failed to resolve via getaddrinfo
        pass
    except Exception:
        # Any unforeseen error results in False for safety
        return False

    # Fallback: directly check the string for loopback patterns
    # IPv4 literal
    if host.startswith("127.") and "." in host:
        # Basic validation of octets
        parts = host.split(".")
        if len(parts) == 4 and all(part.isdigit() and 0 <= int(part) <= 255 for part in parts):
            return True
    # IPv6 literal loopback
    if host.lower() == "::1":
        return True

    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    # Input validation
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer representing file mode bits")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # Abort if file exists and we are not overwriting
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")

    # Ensure parent directories exist
    dir_name = os.path.dirname(os.path.abspath(config_filename))
    if dir_name and not os.path.isdir(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories for '{config_filename}': {exc}") from exc

    # Write file atomically using a temporary file
    tmp_path = None
    try:
        import tempfile
        tmp_fd, tmp_path = tempfile.mkstemp(dir=dir_name,
                                           prefix='.tmp_', suffix=os.path.basename(config_filename))
        os.close(tmp_fd)
        with open(tmp_path, 'w', encoding='utf-8') as tmp_file:
            tmp_file.write(rendered_config)
        os.chmod(tmp_path, mode)
        os.replace(tmp_path, config_filename)
    except Exception as exc:
        # Clean up temporary file if it exists
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass
        raise RuntimeError(f"Failed to write configuration to '{config_filename}': {exc}") from exc
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Ensure matcher provides at least a variable name
    try:
        # Accept both tuple/list or similar objects supporting indexing
        name = matcher[0]
    except Exception as exc:
        raise TypeError("Matcher must be indexable and contain at least the variable name") from exc

    # Extract optional default if present
    default = None
    if hasattr(matcher, "__len__") and len(matcher) > 1:
        default = matcher[1]

    # Look up the variable in the environment
    try:
        return os.environ[name]
    except KeyError:
        if default is None:
            raise RuntimeError(f"Environment variable '{name}' not set and no default provided")
        return default

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid URL: {image_href}") from exc

    scheme = parsed.scheme.lower()
    if scheme not in ("http", "https"):
        raise ValueError(f"Unsupported URL scheme: {scheme}")

    netloc = parsed.netloc
    if not netloc:
        raise ValueError(f"URL missing host (netloc): {image_href}")

    path = parsed.path
    if not path:
        raise ValueError(f"URL missing path component: {image_href}")

    image_id = path.rstrip("/").split("/")[-1]
    if not image_id:
        raise ValueError(f"Cannot extract image ID from URL: {image_href}")

    use_ssl = scheme == "https"
    return image_id, netloc, use_ssl

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    try:
        if not isinstance(pattern, str):
            raise TypeError("pattern must be a string")
        if strip:
            pattern = pattern.strip()
        # Escape regex metacharacters to match the literal string
        escaped = re.escape(pattern)
        # Anchor the pattern to match the entire string
        full_regex = f"^{escaped}$"
        return re.compile(full_regex)
    except Exception as e:
        raise ValueError(f"Failed to convert pattern to regex: {e}") from e

def is_ipv4(target):
    """
    Test if IPv4 address or not
    """
    # If it's already an IPv4Address instance, it's valid
    if isinstance(target, ipaddress.IPv4Address):
        return True
    # Non-string inputs (e.g., None, int, bytes) are not valid IPv4 strings
    if not isinstance(target, str):
        return False
    try:
        # Attempt to construct an IPv4Address; this will raise if invalid
        ipaddress.IPv4Address(target)
        return True
    except (ipaddress.AddressValueError, ValueError):
        return False
    except Exception:
        # Any other unforeseen exception results in False to avoid leaking errors
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Choose a Dumper; default to SafeDumper if none provided
        actual_dumper = dumper if dumper is not None else yaml.SafeDumper
        # Dump the object to a YAML string
        result = yaml.safe_dump(
            obj,
            Dumper=actual_dumper,
            default_flow_style=False,
            allow_unicode=True,
        )
        # Ensure the result is a unicode object on Python 2
        try:
            if isinstance(result, bytes):
                result = result.decode("utf-8")
        except Exception:
            # If transformation fails, just return the original result
            pass
        return result
    except Exception as exc:
        raise RuntimeError("Failed to dump object to YAML string: %s" % exc) from exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate the shape input
    if not isinstance(shape, (tuple, list)):
        raise TypeError(f"shape must be a tuple or list, got {type(shape).__name__}")
    try:
        # Ensure all dimensions are integers
        shape_dims = tuple(int(dim) for dim in shape)
    except Exception as e:
        raise TypeError("All dimensions in shape must be integers") from e
    if any(dim < 0 for dim in shape_dims):
        raise ValueError("All dimensions in shape must be non-negative")

    # Validate and convert dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as e:
        raise TypeError(f"Invalid dtype: {dtype}") from e

    # Create the array
    try:
        return np.zeros(shape_dims, dtype=dtype_obj)
    except Exception as e:
        raise RuntimeError("Failed to create array") from e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
    - dict of configuration filename to corresponding parsed configuration,
    - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import logging
    import os
    import re

    # Validate inputs
    if not isinstance(config_filenames, (list, tuple)):
        raise TypeError("config_filenames must be a list or tuple of filenames")
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a dict or None")
    if not isinstance(resolve_env, bool):
        raise TypeError("resolve_env must be a boolean")

    config_map = {}
    error_records = []
    logger_name = __name__ if __name__ else 'load_configurations'

    def _make_error_record(filename, exc):
        # Create a LogRecord with error level
        exc_tuple = (type(exc), exc, exc.__traceback__)
        return logging.LogRecord(
            logger_name, logging.ERROR,
            pathname=filename, lineno=0,
            msg=f"Error processing {filename}: {exc}",
            args=None, exc_info=exc_tuple
        )

    def _resolve_env_vars(obj):
        """
        Recursively resolve environment variable placeholders in the form ${VAR}
        """
        if isinstance(obj, str):
            # Replace all ${VAR} with value from environment
            def replacer(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return re.sub(r'\$\{([^}]+)\}', replacer, obj)
        elif isinstance(obj, dict):
            return {k: _resolve_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_vars(item) for item in obj]
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if resolve_env:
                data = _resolve_env_vars(data)
            config_map[filename] = data
        except FileNotFoundError as e:
            error_records.append(_make_error_record(filename, e))
        except json.JSONDecodeError as e:
            error_records.append(_make_error_record(filename, e))
        except Exception as e:
            error_records.append(_make_error_record(filename, e))

    # Apply overrides if provided
    if overrides:
        for filename, cfg in config_map.items():
            if isinstance(cfg, dict):
                cfg.update(overrides)
            else:
                # If config is not a dict, skip override and log warning
                warning_msg = f"Overrides ignored for {filename} because config is not a dict"
                warning_record = logging.LogRecord(
                    logger_name, logging.WARNING,
                    pathname=filename, lineno=0,
                    msg=warning_msg,
                    args=None, exc_info=None
                )
                error_records.append(warning_record)

    return config_map, error_records

def force_string(obj):
    """
