@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Validate the protocol_version argument
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be None or a tuple")
            if not all(isinstance(v, int) for v in protocol_version):
                raise TypeError("elements of protocol_version tuple must be integers")

        # Retrieve the mapping of handlers from a class attribute if it exists
        handlers = getattr(cls, "PROTOCOL_HANDLERS", {})
        if not isinstance(handlers, dict):
            # If the attribute exists but isn't a dict, treat it as empty
            handlers = {}

        # If no specific version requested, return all handlers (copy to protect internal state)
        if protocol_version is None:
            return handlers.copy()

        # Return only the handler for the requested version (if it exists)
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    try:
        # Strings and bytes are considered sequences, return as-is
        if isinstance(seq, (str, bytes, bytearray)):
            return seq, type(seq)
        # Check for generic sequence types
        try:
            from collections.abc import Sequence as _Sequence
        except Exception:
            _Sequence = None
        if _Sequence and isinstance(seq, _Sequence):
            return seq, type(seq)
        # If not a sequence, materialize into a list
        if bufsize is None:
            seq_obj = list(seq)
        else:
            import itertools
            seq_obj = list(itertools.islice(seq, bufsize))
    except Exception as exc:
        msg = f"Failed to convert {seq!r} to a sequence: {exc}"
        raise ValueError(msg) from exc
    return seq_obj, type(seq_obj)

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Sanity checks for the `recompute` flag
    if not isinstance(recompute, bool):
        raise ValueError("`recompute` must be a boolean")

    # Helper to actually compute the integral (scale) of the histogram.
    def _compute_scale():
        # Obtain the bin content array; try common attribute names.
        if hasattr(self, "values"):
            counts = self.values
        elif hasattr(self, "data"):
            counts = self.data
        else:
            raise AttributeError("Histogram instance lacks count data")

        # Determine bin widths if possible.
        widths = None
        if hasattr(self, "edges"):
            edges = self.edges
            if len(edges) < 2:
                raise ValueError("Histogram edges must define at least one bin")
            widths = [edges[i + 1] - edges[i] for i in range(len(edges) - 1)]

        # Compute the integral as sum(contents * widths) or just sum(contents)
        if widths is not None and len(counts) == len(widths):
            try:
                integral = float(sum(c * w for c, w in zip(counts, widths)))
            except Exception as exc:
                raise RuntimeError(f"Error computing integral: {exc}") from exc
        else:
            try:
                integral = float(sum(counts))
            except Exception as exc:
                raise RuntimeError(f"Error computing sum of counts: {exc}") from exc

        # Store and return the result
        self._scale = integral
        return integral

    # If no `other` value was supplied, return (or compute) the current scale.
    if other is None:
        if not hasattr(self, "_scale") or recompute:
            _compute_scale()
        return getattr(self, "_scale", 0.0)

    # `other` was supplied: rescale the histogram.
    if not isinstance(other, (int, float)):
        raise TypeError("`other` must be a numeric value representing the desired scale")

    # Ensure we have the current scale value
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or recompute:
        current_scale = _compute_scale()

    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    # Calculate scaling factor and apply it to all bins.
    factor = other / current_scale
    if hasattr(self, "values"):
        counts = self.values
    elif hasattr(self, "data"):
        counts = self.data
    else:
        raise AttributeError("Histogram instance lacks count data")

    try:
        for i in range(len(counts)):
            counts[i] *= factor
    except Exception as exc:
        raise RuntimeError(f"Error applying scaling factor: {exc}") from exc

    # Update stored scale to match the new desired value.
    self._scale = float(other)   # Preserve float semantics
    return None

def scale(self, other=None):
        """
        Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return current scale if no new scale is provided
        if other is None:
            return getattr(self, "_scale", None)

        # Validate new scale is a numeric value
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value")

        # Retrieve the current scale; raise error if unknown or zero
        current_scale = getattr(self, "_scale", None)
        if current_scale is None or current_scale == 0:
            # Try to import the custom exception, fallback to ValueError otherwise
            try:
                raise LenaValueError(
                    "Cannot rescale graph with unknown or zero current scale."
                )
            except NameError:
                raise ValueError(
                    "Cannot rescale graph with unknown or zero current scale."
                )

        # Compute scaling factor
        factor = other / current_scale

        # Identify the last coordinate field (assuming fields are stored in order)
        fields = getattr(self, "_fields", [])
        if not fields:
            raise ValueError("Graph has no coordinate fields to scale")
        last_field = fields[-1]

        # Rescale the data for the last coordinate
        if hasattr(self, "_data") and last_field in self._data:
            coord_data = self._data[last_field]
            if isinstance(coord_data, (list, tuple)):
                for arr in coord_data:
                    arr *= factor
            else:
                coord_data *= factor

        # Rescale any associated errors for the last coordinate
        if hasattr(self, "_errors") and last_field in self._errors:
            error_data = self._errors[last_field]
            if isinstance(error_data, (list, tuple)):
                for err_arr in error_data:
                    err_arr *= factor
            else:
                error_data *= factor

        # Update the stored scale
        self._scale = other
        return None

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        # Resolve candidate if given as a string 'module.ClassName'
        if isinstance(candidate, str):
            module_name, _, class_name = candidate.rpartition('.')
            if not module_name:
                return False
            module = __import__(module_name, fromlist=[class_name])
            candidate_cls = getattr(module, class_name)
        else:
            candidate_cls = candidate

        # Candidate must be a class/type
        if not isinstance(candidate_cls, type):
            return False

        # First check if it is a subclass of the interface
        try:
            if issubclass(candidate_cls, iface):
                return True
        except TypeError:
            # issubclass can raise if either arg is not a class
            pass

        # Gather abstract or expected method names from iface
        required_methods = {
            name
            for name, member in iface.__dict__.items()
            if callable(member) and not name.startswith('_')
        }

        # Gather method names implemented by candidate
        provided_methods = {
            name
            for name, member in candidate_cls.__dict__.items()
            if callable(member) and not name.startswith('_')
        }

        missing = required_methods - provided_methods
        if not missing:
            return True

        if tentative:
            # In tentative mode, accept if at least one required method is present
            return bool(required_methods & provided_methods)

        return False
    except Exception:
        # If anything goes wrong (import error, missing attributes, etc.), treat as not valid
        return False

