    except Exception:
        raise TypeError("bases must be an iterable of classes") from None

    # Validate that each base is a class (i.e., a type)
    for b in bases_list:
        if not isinstance(b, type):
            raise TypeError(f"base {b!r} is not a class")

    # Determine the set of metaclasses from the bases
    base_mcs = set(type(b) for b in bases_list)

    # No bases: default to type
    if not bases_list:
        if explicit_mc is None:
            return type
