def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        try:
            return super().pop(key)
        except KeyError:
            if default is __marker:
                raise
            return default

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure required attributes exist
    if not hasattr(self, "cache") or not hasattr(self, "freq"):
        raise RuntimeError("Cache data structures are not initialized.")
    if not self.cache:
        raise KeyError("Pop from an empty container")

    # Find the minimum frequency among all keys
    try:
        min_freq = min(self.freq.values())
    except ValueError:
        raise KeyError("Frequency mapping is empty")

    # Locate a key that has this minimum frequency
    key_to_remove = None
    for k, f in self.freq.items():
        if f == min_freq:
            key_to_remove = k
            break

    if key_to_remove is None:
        raise RuntimeError("No key found with minimum frequency")

    # Remove the key from both cache and frequency tracking
    value = self.cache.pop(key_to_remove)
    del self.freq[key_to_remove]

    # If any auxiliary structures exist (e.g., buckets), update them here
    # (Omitted due to unknown internal details)

    return (key_to_remove, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to pop the first item (least recently used) using the underlying OrderedDict behavior.
    # This assumes the object inherits from collections.OrderedDict or otherwise implements last=False.
    try:
        return super().popitem(last=False)
    except TypeError:
        # If the superclass does not support the 'last' argument (e.g., plain dict), fall back to popitem().
        # Since Python 3.7+, dict.popitem() pops the last inserted item, not LRU.
        # In this case, raise an informative error because LRU behavior cannot be guaranteed.
        raise TypeError("Base class does not support last=False; cannot pop LRU item") from None
    except KeyError:
        # Reraise with a clearer message if the collection is empty.
        raise KeyError("popitem(): dictionary is empty") from None

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Determine the internal mapping container
    container = None
    for attr in ("_dict", "cache", "data", "items"):
        if hasattr(self, attr):
            container = getattr(self, attr)
            break
    if container is None:
        raise AttributeError("No suitable internal mapping found for popitem")

    # If the container is an OrderedDict, use its popitem with last=True
    if hasattr(container, "popitem"):
        try:
            return container.popitem(last=True)
        except TypeError:
            # In older python versions popitem() defaults to last=True; catch TypeError if mismatched
            return container.popitem()
        except KeyError:
            # container is empty
            raise KeyError("popitem() called on an empty container")

    # Fallback: treat as a dict and pop the most recently inserted key
    if not container:
        raise KeyError("popitem() called on an empty container")
    # In Python 3.7+, dict preserves insertion order
    key = next(reversed(container))
    value = container.pop(key)
    return (key, value)

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches occurrences of "in:" followed by a non-whitespace sequence,
        # optionally surrounded by whitespace.
        pattern = r"\bin:\s*(?P<value>[^\s;,\r\n]+)"
        # Compile with case-insensitive matching to allow variations like "IN:".
        return re.compile(pattern, flags=re.IGNORECASE)
    except re.error as exc:
        # Wrap any pattern compilation error in a ValueError with context.
        raise ValueError(f"Failed to compile in-parameter regex: {exc}") from exc

