def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        data = None
        # Attempt to extract JSON data first
        if hasattr(request, "json") and callable(request.json):
            try:
                data = request.json()
            except Exception:
                data = None
        # Fallback to request body if no JSON method is available
        if data is None and hasattr(request, "body"):
            body = request.body
            if isinstance(body, bytes):
                body = body.decode(errors="ignore")
            if isinstance(body, str):
                try:
                    # Try to safely evaluate a simple literal dict
                    data = eval(body, {"__builtins__": {}})
                except Exception:
                    data = None
        # Use headers as a hint if still no data
        if data is None and hasattr(request, "headers"):
            content_type = request.headers.get("Content-Type", "")
            if "diaspora" in content_type.lower():
                return True
        # If we have parsed a dictionary, run heuristics
        if isinstance(data, dict):
            # Public message: a 'public' key set to True or missing but with a 'content' key
            if data.get("public") is True or ("public" not in data and "content" in data):
                return True
            # Private message: a 'private' key set to True
            if data.get("private") is True:
                return True
            # Legacy payload: special legacy keys
            if data.get("legacy_payload") or "diaspora_signature" in data:
                return True
        return False
    except Exception:
        return False

def identify_request(request: any) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # If the request object is None, it cannot be a Matrix request
        if request is None:
            return False

        # Matrix requests typically start with /_matrix/ in the path or URL
        path = None

        # Common attribute names that might store the request path
        for attr in ("path", "uri", "url", "request_uri", "request_url"):
            if hasattr(request, attr):
                path = getattr(request, attr)
                break

        # If we still didn't find a path, try dictionary-style access
        if path is None and isinstance(request, dict):
            for key in ("path", "uri", "url", "request_uri", "request_url"):
                if key in request:
                    path = request[key]
                    break

        # If still None, attempt to extract from raw request line
        if path is None and hasattr(request, "requestline"):
            line = getattr(request, "requestline")
            # request line is typically "METHOD /path HTTP/1.1"
            parts = str(line).split()
            if len(parts) >= 2:
                path = parts[1]

        # If we got something that looks like a URI, analyze it
        if isinstance(path, str):
            # Normalize to lower case for case-insensitive comparison
            lower = path.lower()
            # Check for canonical Matrix path prefix
            if lower.startswith("/_matrix/"):
                return True
            # Some frameworks may prepend domain part
            # If the string contains "/_matrix/" anywhere, that also indicates Matrix
            if "/_matrix/" in lower:
                return True

        # Some Matrix checks can be based on Authorization header containing "Bearer"
        # but that's ambiguous, so we skip it

        return False
    except Exception:
        # If anything goes wrong in parsing, default to not a Matrix request
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    Accepts a datetime object or an ISO 8601 string.
    Returns a string in UTC formatted as 'YYYY-MM-DDTHH:MM:SSZ'.
    """
    from datetime import datetime, timezone

    if isinstance(dt, datetime):
        # Ensure timezone-aware UTC datetime
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        formatted = dt.strftime('%Y-%m-%dT%H:%M:%S')
    elif isinstance(dt, str):
        try:
            # Handle strings ending with 'Z' or with offset
            if dt.lower().endswith('z'):
                dt_clean = dt[:-1]
                parsed = datetime.fromisoformat(dt_clean)
                parsed = parsed.replace(tzinfo=timezone.utc)
            else:
                parsed = datetime.fromisoformat(dt)
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                else:
                    parsed = parsed.astimezone(timezone.utc)
            formatted = parsed.strftime('%Y-%m-%dT%H:%M:%S')
        except Exception as exc:
            raise ValueError(f"Unable to parse datetime string: {dt}") from exc
    else:
        raise TypeError("format_dt expects a datetime object or ISO 8601 string")

    return f"{formatted}Z"

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote URL to determine the content type.

    Returns the value of the "Content-Type" header if available; otherwise,
    returns None. Handles common network errors gracefully.
    """
    if not isinstance(url, str) or not url:
        return None
    try:
        # Dynamically import urllib modules to avoid top-level import statements.
        urllib_request = __import__('urllib.request')
        urllib_error = __import__('urllib.error')
        try:
            req = urllib_request.Request(url, method='HEAD')
        except TypeError:
            # For older Python versions that don't support the method kwarg
            req = urllib_request.Request(url)
            req.get_method = lambda: 'HEAD'
        with urllib_request.urlopen(req, timeout=10) as response:
            return response.headers.get('Content-Type')
    except (urllib_error.URLError, urllib_error.HTTPError, ValueError, Exception):
        # ValueError covers malformed URLs; any other exception results in None.
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise TypeError("node cannot be None")

    try:
        children = list(node)
    except Exception as exc:
        raise TypeError(f"Expected an XML element, got {type(node).__name__}") from exc

    result = {}
    for child in children:
        try:
            key = child.tag
        except AttributeError as exc:
            # Skip objects that do not have a tag attribute
            continue

        # Retrieve text content; strip whitespace if present
        try:
            value = child.text.strip() if child.text else ''
        except Exception:
            value = ''

        # Store in dict, grouping duplicate tags into lists
        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import hashlib
        import base64
    except Exception:
        return False
    # Validate input types
    try:
        if not isinstance(public_key, (bytes, str)):
            return False
        if not isinstance(doc, (bytes, str)):
            return False
        if not isinstance(signature, (bytes, str)):
            return False

        # Normalize to bytes
        if isinstance(public_key, str):
            public_key_bytes = public_key.encode('utf-8')
        else:
            public_key_bytes = public_key

        if isinstance(doc, str):
            doc_bytes = doc.encode('utf-8')
        else:
            doc_bytes = doc

        if isinstance(signature, str):
            signature_bytes = signature.encode('utf-8')
        else:
            signature_bytes = signature

        # Compute SHA-256 digest of the document
        digest = hashlib.sha256(doc_bytes).digest()

        # Expect the signature to be the base64 encoding of the digest
        expected_signature = base64.b64encode(digest)

        # Return whether the provided signature matches the expected one
        return signature_bytes == expected_signature
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    from typing import Dict
    try:
        import json
        return json.loads(document)
    except Exception:
        pass
    try:
        import xml.etree.ElementTree as ET
        # Attempt to parse XRD (XML) format
        try:
            root = ET.fromstring(document)
        except ET.ParseError as exc:
            raise ValueError(f"Unable to parse webfinger document: {exc}") from exc

        def local_name(tag: str) -> str:
            return tag.split('}', 1)[-1] if '}' in tag else tag

        result: Dict = {"subject": None, "aliases": [], "links": []}
        for elem in root.iter():
            tag = local_name(elem.tag)
            if tag == "Subject":
                result["subject"] = elem.text
            elif tag == "Alias":
                if elem.text:
                    result["aliases"].append(elem.text)
            elif tag == "Link":
                # The Link element may contain attributes like rel, href, type
                result["links"].append({k: v for k, v in elem.attrib.items()})
            # For completeness, include Property extraction if needed
            elif tag == "Property":
                # Attempt to parse property name and value from nested elements
                title = None
                value = None
                for child in elem:
                    child_tag = local_name(child.tag)
                    if child_tag == "Title":
                        title = child.text
                    elif child_tag == "Value":
                        value = child.text
                if title:
                    if "properties" not in result:
                        result["properties"] = {}
                    result["properties"][title] = value if value is not None else None
            elif tag == "Title":
                # ambiguous: could be a standalone title; ignore for now
                pass

        # Clean up if subject remains None and no results
        if result["subject"] is None and not result["aliases"] and not result["links"]:
            raise ValueError("No recognizable fields found in XRD webfinger document.")
        return result
    except Exception as exc:
        raise ValueError(f"Failed to parse webfinger document: {exc}") from exc

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance (XML Element)
    """
    import urllib.request
    import urllib.error
    import xml.etree.ElementTree as ET

    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")
    host = host.strip()
    if not host.startswith(('http://', 'https://')):
        host = 'https://' + host
    if not host.endswith('/'):
        host = host.rstrip('/')
    url = host + '/.well-known/host-meta'
    try:
        req = urllib.request.Request(
            url,
            headers={'Accept': 'application/xrd+xml'}
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(f"Failed to fetch host‑meta: HTTP {resp.status}")
            data = resp.read()
            try:
                xrd = ET.fromstring(data)
            except ET.ParseError as e:
                raise RuntimeError("Failed to parse host‑meta XML") from e
    except urllib.error.URLError as e:
        raise RuntimeError(f"Failed to retrieve host‑meta: {e}") from e
    return xrd

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST (or other HTTP verb).

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post`` or ``requests.request``.
    The function handles ``data`` that is a dictionary (form-encoded), bytes, or a file-like object.
    It returns a tuple of (status code, error).  ``status code`` is ``None`` if an error occurred,
    and ``error`` is ``None`` when the request succeeded.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Import requests lazily to avoid imposing a module import on callers that don't need it.
    try:
        import requests
    except Exception as exc:
        return None, exc

    if not isinstance(method, str):
        return None, ValueError("method must be a string")

    method_lower = method.lower()
    method_upper = method.upper()

    # Prepare data for requests
    if data is None:
        body = None
    elif isinstance(data, dict):
        body = data
    elif hasattr(data, "read"):
        # Ensure we read from file-like object
        try:
            body = data.read()
        except Exception as exc:
            return None, exc
        # If read returned a string, encode to bytes (requests expects bytes or str)
        if isinstance(body, str):
            body = body.encode("utf-8")
    else:
        body = data  # bytes or str

    # Perform the request, ignoring positional *args for compatibility with the original spec
    try:
        if method_lower == "post":
            resp = requests.post(url, data=body, timeout=timeout, **kwargs)
        else:
            resp = requests.request(method_upper, url, data=body, timeout=timeout, **kwargs)
        return resp.status_code, None
    except Exception as exc:
        return None, exc

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type
    """
    from pathlib import Path
    if settings_dirs is None:
        return []
    # Normalize settings_dirs to a list of paths
    if isinstance(settings_dirs, (str, Path)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            raise TypeError("settings_dirs must be a string, Path, or an iterable of paths")
    if spec_option is None:
        spec = "*.ini"
    elif isinstance(spec_option, str):
        spec = spec_option
    else:
        raise TypeError("spec_option must be a string pattern (e.g., '*.ini')")
    file_names = []
    for d in dirs:
        try:
            path = Path(d)
            if not path.exists() or not path.is_dir():
                continue
            for file_path in path.rglob(spec):
                if file_path.is_file():
                    file_names.append(str(file_path.resolve()))
        except OSError:
            # skip directories that cannot be accessed
            continue
    return sorted(file_names)

