@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # import locally to avoid unnecessary global imports
        import yaml

        if spec_content is None:
            raise IRValidatorException("Spec content is required but was not provided")

        # Load YAML from the provided content
        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML content: {exc}") from exc

        # Ensure the parsed data is a mapping
        if not isinstance(data, dict):
            raise IRValidatorException(f"Spec content must be a mapping (dict), got {type(data).__name__}")

        # Define a set of required fields for the spec
        required_keys = {"name", "type", "version"}
        missing_keys = required_keys - data.keys()
        if missing_keys:
            raise IRValidatorException(
                f"Missing required spec fields: {', '.join(sorted(missing_keys))}"
            )

        return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # Local imports to avoid module-level imports
        import yaml
        try:
            # Try to import the custom exception; if not available, fall back to a simple subclass
            from exceptions import IRValidatorException  # type: ignore
        except Exception:
            class IRValidatorException(Exception):
                """Fallback exception if the real one is not available."""
                pass

        if not yaml_file:
            raise ValueError("yaml_file must be provided")

        # Load the YAML data
        try:
            with open(yaml_file, "r", encoding="utf-8") as fh:
                data = yaml.safe_load(fh)
        except (OSError, yaml.YAMLError) as exc:
            raise IRValidatorException(f"Error loading YAML file '{yaml_file}': {exc}") from exc

        # Ensure the top-level structure is a mapping
        if not isinstance(data, dict):
            raise IRValidatorException(
                f"Top-level YAML data must be a mapping (dict), got {type(data).__name__}"
            )

        # Determine required fields (if any) from a class attribute
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields:
            missing = [field for field in required_fields if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required field(s) in YAML file '{yaml_file}': "
                    f"{', '.join(missing)}"
                )

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    from copy import deepcopy
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")
    try:
        # Recursive helper to resolve an individual group, handling nested includes
        def _resolve_group(group, group_defs, visited):
            result = deepcopy(group)
            includes = result.pop('include', None)
            if includes:
                if isinstance(includes, str):
                    names = [includes]
                elif isinstance(includes, (list, tuple)):
                    names = list(includes)
                else:
                    raise ValueError("'include' must be a string or a list/tuple of strings")
                for name in names:
                    if name in visited:
                        raise ValueError(f"Circular include detected for group '{name}'")
                    if name not in group_defs:
                        raise KeyError(f"Included group '{name}' not found")
                    visited.add(name)
                    sub = _resolve_group(group_defs[name], group_defs, visited.copy())
                    result.update(sub)
            return result

        groups = parser_dict.get('groups', {})
        if not groups:
            # Nothing to resolve
            return deepcopy(parser_dict)

        # Resolve top‑level includes if present
        includes = parser_dict.get('include')
        if not includes:
            return deepcopy(parser_dict)

        resolved = deepcopy(parser_dict)
        resolved.pop('include')
        if isinstance(includes, str):
            names = [includes]
        elif isinstance(includes, (list, tuple)):
            names = list(includes)
        else:
            raise ValueError("'include' must be a string or a list/tuple of strings")

        for name in names:
            if name not in groups:
                raise KeyError(f"Included group '{name}' not found")
            sub = _resolve_group(groups[name], groups, visited=set([name]))
            resolved.update(sub)

        # Optionally remove the groups dict after merging if desired
        resolved.pop('groups', None)
        return resolved
    except Exception as exc:
        raise ValueError(f"Failed to resolve groups: {exc}") from exc

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, 'spec', {})
    except Exception:
        spec = {}
    if not isinstance(spec, dict):
        return defaults

    parameters = spec.get('parameters', [])
    # Ensure parameters is iterable
    if not isinstance(parameters, (list, tuple)):
        parameters = []

    import os  # local import to avoid global import

    for param in parameters:
        if not isinstance(param, dict):
            continue
        name = param.get('name')
        if not name:
            continue

        # Check for environment variable override
        env_var = param.get('env')
        if env_var:
            env_value = os.getenv(env_var)
            if env_value is not None:
                # Convert to appropriate type if default exists (e.g., int, bool)
                try:
                    default_val = param.get('default')
                    if default_val is not None:
                        if isinstance(default_val, bool):
                            env_value = env_value.lower() in ('1', 'true', 'yes')
                        elif isinstance(default_val, int):
                            env_value = int(env_value)
                        elif isinstance(default_val, float):
                            env_value = float(env_value)
                    defaults[name] = env_value
                    continue
                except Exception:
                    # fall back to string value
                    defaults[name] = env_value
                    continue

        # Fallback to spec default if provided
        if 'default' in param:
            defaults[name] = param['default']

    # Override with any user-provided arguments if present
    user_args = getattr(self, 'args', None)
    if isinstance(user_args, dict):
        for k, v in user_args.items():
            if v is not None:
                defaults[k] = v

    return defaults

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type validation for robustness
    if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
        raise TypeError("cli_args and answer_file_args must be dictionaries")

    # Retrieve the set/list of deprecated argument names, if defined
    deprecated = getattr(self, "deprecated_args", set())
    if not isinstance(deprecated, (set, list, tuple)):
        # If some other iterable type is provided, try converting to set
        try:
            deprecated = set(deprecated)
        except Exception:
            # Malformed deprecated list: treat as empty
            deprecated = set()

    # Helper for logging a deprecation warning
    def _log_deprecation(source, arg_name):
        try:
            # Use logger if available, otherwise fallback to print
            if hasattr(self, "logger") and hasattr(self.logger, "warning"):
                self.logger.warning(f"{source} argument '{arg_name}' is deprecated and will be ignored.")
            else:
                print(f"[WARNING] {source} argument '{arg_name}' is deprecated and will be ignored.")
        except Exception as e:
            # If logging fails, silently ignore to avoid breaking flow
            pass

    # Check both argument sources for deprecated keys
    for source_name, arg_dict in (("CLI", cli_args), ("Answer file", answer_file_args)):
        for key in arg_dict:
            try:
                if key in deprecated:
                    _log_deprecation(source_name, key)
            except Exception:
                # Unexpected key type or internal error: skip this key
                continue
    # Method intentionally returns None; all useful actions are performed via logging."""

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")

    # Attempt to retrieve the command options container
    try:
        command_options_container = getattr(self, "command_options", {})
    except Exception:
        # If attribute access itself fails, treat as empty container
        command_options_container = {}

    # Ensure the container is a dictionary
    if not isinstance(command_options_container, dict):
        raise TypeError("Expected 'command_options' to be a dict")

    # Look up the options for the requested command
    raw_options = command_options_container.get(command_name)

    # If the command is unknown, return an empty list
    if raw_options is None:
        return []

    # Depending on how options are stored, normalize the result to a list.
    if isinstance(raw_options, list):
        return raw_options
    if isinstance(raw_options, dict):
        # Return the values (e.g., option spec objects) rather than keys
        return list(raw_options.values())
    # For any other type, wrap it in a list
    return [raw_options]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate types of the arguments
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, str):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    # Attempt to retrieve the specification from the internal storage
    try:
        # The implementation assumes that the class has an attribute `_option_specs`
        # structured as: {command_name: {argument_name: spec_dict}}
        spec = self._option_specs[command_name][argument_name]
    except AttributeError as e:
        # The expected attribute does not exist on the instance
        raise AttributeError("The instance does not have the expected `_option_specs` attribute.") from e
    except KeyError as e:
        # Either the command or the argument name was not found
        missing = command_name if command_name not in getattr(self, "_option_specs", {}) else argument_name
        context = "command" if command_name not in getattr(self, "_option_specs", {}) else "option"
        raise KeyError(f"{context} '{missing}' not found in the specifications.") from e
    except Exception as e:
        # Catch any other unexpected runtime errors
        raise RuntimeError("An unexpected error occurred while retrieving the option specification.") from e

    return spec

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")
    # Retrieve the list of required argument names; fall back to empty list if not defined.
    required = getattr(self, "required_args", [])
    if not isinstance(required, (list, tuple, set)):
        raise TypeError(f"self.required_args must be an iterable, got {type(required).__name__}")
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")
    return None

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Ensure args is a dict of name -> value for easy lookup.
        if not isinstance(args, dict):
            try:
                args = dict(args)
            except Exception:
                args = {}

        required_when_names = []

        for opt in options_spec:
            # Skipping non‑dict specs or specs without a name.
            if not isinstance(opt, dict):
                continue
            opt_name = opt.get("name")
            if not isinstance(opt_name, str):
                continue

            # Skip if the option has no required_when condition.
            if "required_when" not in opt:
                continue

            condition = opt["required_when"]
            try:
                # If condition is a string, evaluate it with the args as
                # local variables.  For safety we disable builtins.
                if isinstance(condition, str):
                    # Allow referencing command_name directly.
                    local_vars = dict(args)
                    local_vars["command_name"] = command_name
                    # Evaluate the condition; if true, add the argument name.
                    if eval(condition, {"__builtins__": {}}, local_vars):
                        required_when_names.append(opt_name)
                # If the condition is callable, call it with args.
                elif callable(condition):
                    if condition(args):
                        required_when_names.append(opt_name)
                # For any other truthy value consider it satisfied.
                else:
                    if condition:
                        required_when_names.append(opt_name)
            except Exception:
                # Any error in evaluating a condition is treated as
                # non‑met; the argument is simply not considered required.
                continue

        return required_when_names

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments. The arguments can be provided as a
        dictionary mapping argument names to values, or as a list/tuple
        of values. For each value that is a string or a collection, the
        length is compared against a hard‑coded maximum of 255
        characters/items. If an argument exceeds this limit a
        ``ValueError`` is raised. Unsupported argument types are ignored.
    """
    # If no arguments were supplied there is nothing to validate.
    if args is None:
        return

    try:
        # Normalize the arguments into an iterable of (name, value) pairs.
        if isinstance(args, dict):
            arg_iter = args.items()
        elif isinstance(args, (list, tuple)):
            # Use the index as the argument name in list/tuple case.
            arg_iter = enumerate(args)
        else:
            raise TypeError("`args` must be a dict or a list/tuple")

        # Iterate over each argument and validate its length.
        for name, value in arg_iter:
            # Only strings and collections have a length that can be checked.
            if isinstance(value, (str, list, tuple, set, dict)):
                if len(value) > 255:
                    # Create a human‑readable name for the offending argument.
                    arg_name = str(name) if isinstance(args, dict) else f"arg{index}"
                    raise ValueError(
                        f"Argument '{arg_name}' exceeds maximum length of 255."
                    )
    except Exception as exc:
        # Store the original exception context to aid debugging.
        raise ValueError(
            f"Failed to validate argument lengths: {exc}"
        ) from exc

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Either a dictionary with keys
                 'value', 'min', and 'max', or a list/tuple of such
                 dictionaries. Raises ValueError if the arguments are
                 invalid or the value is out of bounds.
    :return: True if the value(s) are within the specified bounds.
    """
    def _check_one(arg):
        if not isinstance(arg, dict):
            raise ValueError(f"Argument entry must be a dict, got {type(arg).__name__}")
        for key in ('value', 'min', 'max'):
            if key not in arg:
                raise ValueError(f"Missing required key '{key}' in argument entry")
        value = arg['value']
        min_val = arg['min']
        max_val = arg['max']
        if value is None or min_val is None or max_val is None:
            raise ValueError("None is not allowed for 'value', 'min', or 'max'")
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(f"Value {value} is not between {min_val} and {max_val}")
        except TypeError:
            raise ValueError("'min', 'max', and 'value' must be comparable types")
        return True

    try:
        if isinstance(args, (list, tuple)):
            for arg in args:
                _check_one(arg)
        elif isinstance(args, dict):
            _check_one(args)
        else:
            raise ValueError(f"args must be a dict or list/tuple of dicts, got {type(args).__name__}")
    except Exception as exc:
        # Re-raise with a clear message
        raise ValueError(f"validate_min_max_args failed: {exc}") from None

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """
        Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        try:
            # Basic validation of mandatory fields
            if not isinstance(subcommand, str) or not subcommand:
                raise TypeError("subcommand must be a non-empty string")
            if not isinstance(type_name, str) or not type_name:
                raise TypeError("type_name must be a non-empty string")
            if not isinstance(option_name, str) or not option_name:
                raise TypeError("option_name must be a non-empty string")

            # spec_option can be any JSON serializable object; if None, treat as empty dict
            if spec_option is None:
                spec_dict = {}
            elif isinstance(spec_option, dict):
                spec_dict = spec_option
            else:
                # Try to coerce common sequence types into a dict with indices as keys
                if hasattr(spec_option, "__iter__"):
                    spec_dict = {i: v for i, v in enumerate(spec_option)}
                else:
                    # Wrap a single value into a dict under key 'value'
                    spec_dict = {"value": spec_option}

            # Construct the complex type representation
            complex_type = {
                "subcommand": subcommand,
                "type_name": type_name,
                "option_name": option_name,
                "specification": spec_dict
            }
            return complex_type

        except Exception as exc:
            # Preserve the original traceback for debugging purposes
            raise RuntimeError(
                f"Failed to create complex argument type for '{option_name}' "
                f"on subcommand '{subcommand}': {exc}"
            ) from exc

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: Iterable of extra-vars represented as ``key=value`` strings,
                           dictionaries, or tuples.
        :return: The updated dictionary
        """
        # Validate input
        if not isinstance(vars_dict, dict):
            raise TypeError(f"'vars_dict' must be a dict, got {type(vars_dict).__name__}")

        # Nothing to merge
        if extra_vars is None:
            return vars_dict

        # If a dict is given, just update
        if isinstance(extra_vars, dict):
            try:
                vars_dict.update(extra_vars)
            except Exception as e:
                raise ValueError(f"Failed to update vars_dict with {extra_vars!r}: {e}") from e
            return vars_dict

        # Otherwise, iterate over the provided iterable
        try:
            for item in extra_vars:
                # Handle key=value strings
                if isinstance(item, str):
                    if '=' in item:
                        key, value = item.split('=', 1)
                        key = key.strip()
                        value = value.strip()
                        if key:  # ignore empty keys
                            vars_dict[key] = value
                    else:
                        # Skip or warn about malformed string
                        continue
                # Handle dictionaries
                elif isinstance(item, dict):
                    vars_dict.update(item)
                # Handle tuple or list with two elements: (key, value)
                elif isinstance(item, (tuple, list)) and len(item) == 2:
                    key, value = item
                    if isinstance(key, str) and key:
                        vars_dict[key] = value
                else:
                    # Unsupported type: ignore
                    continue
        except Exception as e:
            # Unexpected error during merge: raise a ValueError
            raise ValueError(f"Error while merging extra_vars: {e}") from e

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

        :param ir_workspace: An Infrared Workspace object represents the active
        workspace
        :param ir_plugin: An InfraredPlugin object of the current plugin
        :param playbook_path: the playbook to invoke
        :param verbose: Ansible verbosity level
        :param extra_vars: dict. Passed to Ansible as extra-vars
        :param ansible_args: dict of ansible-playbook arguments to plumb down
            directly to Ansible.
    """
    import subprocess
    import json

    # Basic command
    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append("-" + "v" * min(verbose, 5))
        elif isinstance(verbose, str):
            # Allow 'v', 'vv', etc.
            vv = "v" * min(len(verbose), 5)
            cmd.append("-" + vv)

    # Extra vars
    if extra_vars:
        try:
            extra_json = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", extra_json])
        except (TypeError, ValueError) as exc:
            raise ValueError(f"extra_vars must be JSON serializable: {exc}") from exc

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if key.startswith("-"):
                flag = key
            else:
                flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # If False, skip
            elif value is None:
                # Just a flag
                cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.root if hasattr(ir_workspace, "root") else None,
            capture_output=True,
            text=True,
            check=False,  # We'll handle non-zero exit manually
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

    # Handle non-zero exit
    if result.returncode != 0:
        err_msg = f"ansible-playbook exited with {result.returncode}\n" \
                  f"stdout:\n{result.stdout}\n" \
                  f"stderr:\n{result.stderr}"
        raise RuntimeError(err_msg)

    return result

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper for flattening nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    spec = None
    # Determine possible spec file names
    possible_filenames = ['plugin.yaml', 'plugin.yml', 'plugin.json']

    for filename in possible_filenames:
        spec_path = os.path.join(plugin_dir, filename)
        if os.path.isfile(spec_path):
            try:
                if filename.endswith('.json'):
                    with open(spec_path, 'r', encoding='utf-8') as f:
                        spec = json.load(f)
                else:
                    try:
                        import yaml
                    except Exception:
                        # yaml not available, fallback to json if possible
                        with open(spec_path, 'r', encoding='utf-8') as f:
                            try:
                                spec = json.load(f)
                            except json.JSONDecodeError:
                                # Can't parse
                                spec = {}
                    else:
                        with open(spec_path, 'r', encoding='utf-8') as f:
                            spec = yaml.safe_load(f)
                break
            except Exception:
                # Parsing error results in empty spec
                spec = {}
                break

    if spec is None:
        # No spec file found; return empty dictionary
        return {}

    if not isinstance(spec, dict):
        # Spec is not a dict; cannot flatten
        return {}

    try:
        flat_spec = _flatten(spec)
    except Exception:
        # In case of unexpected errors during flattening
        return {}

    return flat_spec

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        # Determine the configuration path to use
        config_path = getattr(self, 'config_path', None)
        if config_path is None:
            # Fallback to a sensible default if the attribute is missing
            config_path = 'config.yaml'
        # Only set the variable if it hasn't been defined already
        if os.getenv('CONFIG_PATH') is None:
            os.environ['CONFIG_PATH'] = config_path
    except Exception as exc:
        # Provide a clear error message while preserving the original exception
        raise RuntimeError(f"Failed to inject config path: {exc}") from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    try:
        # Use os.path for path normalization and relative path calculation
        import os
        norm_path = os.path.normpath(path)
        norm_root = os.path.normpath(root)
        # Ensure that root is actually a prefix of path
        try:
            if os.path.commonpath([norm_path, norm_root]) != norm_root:
                raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
        except Exception as e:
            raise ValueError(f"Failed to determine common path: {e}")
        # Compute the relative path
        rel = os.path.relpath(norm_path, norm_root)
        # If the relative path is '.', return empty string to indicate no remainder
        return '' if rel == '.' else rel
    except Exception as exc:
        raise ValueError(f"Unable to strip root: {exc}") from exc
